<?php $title='Productos'; ?><h1 class="title">Productos disponibles</h1><p class="subtitle is-6">Consulta los productos de las rifas activas.</p><div class="columns is-multiline"><?php foreach($raffles as $r): ?><div class="column is-one-third"><div class="card raffle-card"><div class="card-image"><?php if($r['image_path']): ?><figure class="image is-4by3"><img src="<?= e($r['image_path']) ?>" alt="<?= e($r['product_name']) ?>"></figure><?php else: ?><div class="placeholder-image">Sin imagen</div><?php endif; ?></div><div class="card-content"><div class="level"><p class="title is-5 mb-0"><?= e($r['product_name']) ?></p><span class="tag is-success">Activa</span></div><?php if(\App\Core\Auth::check() && !\App\Core\Auth::isAdmin()): ?><div class="content"><?php if(\App\Core\Auth::canBuy()): ?><p><strong><?= money($r['ticket_price']) ?></strong> por boleto</p><?php endif; ?><p><?= (int)$r['sold_count'] ?> / <?= (int)$r['tickets_to_target'] ?> vendidos</p><progress class="progress is-primary" value="<?= (int)$r['sold_count'] ?>" max="<?= (int)$r['tickets_to_target'] ?>"></progress></div><?php endif; ?><a class="button is-link is-fullwidth" href="<?= route('raffle',['id'=>$r['id']]) ?>">Ver producto</a></div></div></div><?php endforeach; ?></div>
